import json
import os
import pathlib
import queue
import shutil
import threading
import time
import subprocess
import sys

request = json.load(sys.stdin)
trigger = request.get('trigger') or {}
args = trigger.get('args') or {}
state_dir = pathlib.Path(request['state_dir'])
sessions_path = state_dir / 'sessions.json'
try:
    sessions = json.loads(sessions_path.read_text(encoding='utf-8'))
except FileNotFoundError:
    sessions = {}
action = trigger.get('action')
if action == 'reset_session':
    key = args.get('session_key')
    if key:
        sessions.pop(key, None)
    else:
        sessions = {}
    sessions_path.write_text(json.dumps(sessions, ensure_ascii=False), encoding='utf-8')
    print(json.dumps({'result': {'cleared': True}}))
    sys.exit(0)
if action != 'ask':
    raise ValueError('알 수 없는 동작입니다')
key = args.get('session_key') or 'default'
prompt = args.get('prompt') or ''
parts = [args.get('system_prompt') or '']
for turn in sessions.get(key, [])[-6:]:
    parts.extend(['사용자: ' + turn['prompt'], '응답: ' + turn['reply']])
parts.append('사용자: ' + prompt)
composed = '\n\n'.join(part for part in parts if part)
specs = request.get('storage', {}).get('agents') or []
selected = args.get('agent_id') or ''
specs = sorted(specs, key=lambda item: item.get('id') != selected) if selected else specs


def acp(spec, cmd, env):
    process = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True, encoding='utf-8', cwd=state_dir, env=env, bufsize=1)
    lines = queue.Queue()
    def collect_lines():
        for line in process.stdout:
            lines.put(line)
        lines.put(None)
    threading.Thread(target=collect_lines, daemon=True).start()
    deadline = time.monotonic() + 60
    def send(message):
        process.stdin.write(json.dumps(message, ensure_ascii=False) + '\n')
        process.stdin.flush()
    def read_until(target, chunks):
        while True:
            try:
                line = lines.get(timeout=max(0, deadline - time.monotonic()))
            except queue.Empty as error:
                raise RuntimeError('에이전트 응답 시간이 초과되었습니다') from error
            if line is None:
                raise RuntimeError('에이전트 응답이 끊겼습니다')
            message = json.loads(line)
            if 'id' in message and 'method' in message:
                send({'jsonrpc': '2.0', 'id': message['id'], 'result': {'outcome': {'outcome': 'cancelled'}}})
            elif message.get('method') == 'session/update':
                update = message.get('params', {}).get('update', {})
                content = update.get('content') or {}
                if update.get('sessionUpdate') == 'agent_message_chunk' and content.get('text'):
                    chunks.append(content['text'])
            elif message.get('id') == target:
                if 'error' in message:
                    raise RuntimeError(str(message['error']))
                return message.get('result') or {}
    try:
        send({'jsonrpc': '2.0', 'id': 1, 'method': 'initialize', 'params': {'protocolVersion': 1}})
        read_until(1, [])
        send({'jsonrpc': '2.0', 'id': 2, 'method': 'session/new', 'params': {'cwd': str(state_dir), 'mcpServers': []}})
        session_id = read_until(2, [])['sessionId']
        send({'jsonrpc': '2.0', 'id': 3, 'method': 'session/prompt', 'params': {'sessionId': session_id, 'prompt': [{'type': 'text', 'text': composed}]}})
        chunks = []
        read_until(3, chunks)
        return ''.join(chunks)
    finally:
        process.terminate()
        try:
            process.wait(timeout=2)
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait()

errors = []
for spec in specs:
    try:
        env = os.environ.copy()
        env.update(spec.get('env') or {})
        argv = spec.get('args') or []
        command = shutil.which(spec['command'], path=env.get('PATH')) or spec['command']
        if any('{prompt}' in item for item in argv):
            cmd = [command] + [item.replace('{prompt}', composed) for item in argv]
            reply = subprocess.run(cmd, capture_output=True, text=True, encoding='utf-8', cwd=state_dir, env=env, timeout=60, check=True).stdout.strip()
        else:
            reply = acp(spec, [command] + argv, env).strip()
        if not reply:
            raise RuntimeError('빈 응답입니다')
        turns = sessions.setdefault(key, [])
        turns.append({'prompt': prompt, 'reply': reply})
        sessions[key] = turns[-6:]
        sessions_path.write_text(json.dumps(sessions, ensure_ascii=False), encoding='utf-8')
        print(json.dumps({'result': {'reply': reply, 'agent_id': spec.get('id', ''), 'session_key': key}}, ensure_ascii=False))
        break
    except (OSError, ValueError, KeyError, subprocess.SubprocessError, RuntimeError) as error:
        errors.append(str(error))
else:
    raise RuntimeError('사용할 에이전트가 없습니다: ' + '; '.join(errors))

